<script setup lang="ts">import maplibregl from"maplibre-gl";const props=defineProps<{point:{latitude:number;longitude:number;radiusMeters:number}}>();const config=useRuntimeConfig(),container=ref<HTMLElement|null>(null);let map:maplibregl.Map|undefined;onMounted(()=>{if(!container.value)return;map=new maplibregl.Map({container:container.value,style:String(config.public.mapStyleUrl),center:[props.point.longitude,props.point.latitude],zoom:13,attributionControl:{compact:true}});map.on("load",()=>{map?.addSource("approximate-location",{type:"geojson",data:{type:"Feature",properties:{},geometry:{type:"Point",coordinates:[props.point.longitude,props.point.latitude]}}});map?.addLayer({id:"approximate-location-area",type:"circle",source:"approximate-location",paint:{"circle-radius":50,"circle-color":"#a62626","circle-opacity":.18,"circle-stroke-width":2,"circle-stroke-color":"#a62626"}})});map.scrollZoom.disable()});onBeforeUnmount(()=>map?.remove());</script>
<template><section class="approximate-map"><div ref="container" class="approximate-map__canvas" aria-label="محدوده تقریبی آگهی"></div><p>برای حفظ حریم خصوصی فروشنده، مکان با شعاع تقریبی {{ point.radiusMeters.toLocaleString('fa-IR') }} متر نمایش داده می‌شود.</p></section></template>
